<script setup lang="ts">
import {ref,computed,watch,onUnmounted,inject} from 'vue'
import {useAuthStore} from '../../../stores/auth'
import {createAdminTaskAccess,taskAccessKey,taskIdentity} from './taskAccess'
import {listAdminTaskAttempts} from '../../../api/adminTasks'
import type {Attempt,Page} from '../../../api/adminTasks'
import {attemptStateLabel,formatTaskTime,formatElapsed} from './taskPresentation'
const props=defineProps<{taskId:string}>(),auth=useAuthStore()
const access=inject(taskAccessKey,()=>createAdminTaskAccess(()=>taskIdentity(auth.profile),()=>auth.refresh()),true)
const canRead=computed(()=>!!auth.profile?.userId&&auth.profile.role==='ADMIN'&&!access.denied.value)
const result=ref<Page<Attempt>|null>(null),busy=ref(false),error=ref(''),stale=ref(false),cursors=ref<(string|undefined)[]>([undefined]),pageIndex=ref(0)
let epoch=0
async function load(index=0,refresh=false){if(!canRead.value||busy.value)return;const n=++epoch,identity=taskIdentity(auth.profile);busy.value=true;error.value='';if(refresh)index=0;const cursor=refresh?undefined:cursors.value[index];try{const value=await listAdminTaskAttempts(props.taskId,20,cursor);if(n!==epoch||!canRead.value)return;result.value=value;pageIndex.value=index;cursors.value=refresh?[undefined]:cursors.value.slice(0,index+1);if(value.nextCursor)cursors.value[index+1]=value.nextCursor;stale.value=false}catch(e){if(access.reject(e,identity))return;if(n!==epoch)return;const failure=e as {status?:number;message?:string};if([401,403,404].includes(failure.status??0))result.value=null;else stale.value=result.value!==null;error.value=failure.message||'尝试记录未能读取'}finally{if(n===epoch)busy.value=false}}
watch([()=>props.taskId,()=>auth.profile?.userId,()=>auth.profile?.role,()=>access.denied.value],()=>{epoch++;result.value=null;busy.value=false;error.value='';stale.value=false;cursors.value=[undefined];pageIndex.value=0;if(canRead.value)void load()},{immediate:true,flush:'sync'})
onUnmounted(()=>{epoch++})
</script>
<template><section v-if="canRead" class="task-attempts" aria-label="任务尝试历史"><h3>执行尝试记录</h3><p class="small hint">序号保留原始执行顺序；新增尝试可在刷新后查看，浏览期间状态可能更新。</p><button type="button" data-test="attempt-refresh" :disabled="busy" @click="load(0,true)">{{busy?'读取中…':'刷新尝试记录'}}</button><p v-if="error" class="task-error" role="alert">{{error}}</p><p v-if="stale" class="task-stale">尝试记录尚未刷新，保留上次读取结果。</p><p v-if="result" class="small" aria-live="polite">查询时间：{{formatTaskTime(result.queriedAt)}}（上海时间）</p><div v-if="result?.items.length" class="task-scroll" role="region" aria-label="执行尝试表，可横向滚动" tabindex="0"><table><caption class="sr-only">所选任务的执行尝试</caption><thead><tr><th scope="col">原序号</th><th scope="col">状态</th><th scope="col">开始 / 结束</th><th scope="col">执行耗时</th><th scope="col">原因 / 结果引用</th></tr></thead><tbody><tr v-for="item in result.items" :key="item.ordinal"><td>{{item.ordinal}}</td><td>{{attemptStateLabel(item.state)}}</td><td>{{formatTaskTime(item.startedAt)}}<br/>{{formatTaskTime(item.finishedAt)}}</td><td>{{formatElapsed(item.durationMillis,item.finishedAt)}}</td><td>{{item.reason.message}}<span v-if="item.reason.code">（{{item.reason.code}}）</span><br/><span class="mono">{{item.resultVersionId||'暂无结果版本'}}</span></td></tr></tbody></table></div><p v-else-if="result&&!busy" role="status">暂无执行尝试记录。</p><div class="task-actions"><button type="button" data-test="attempt-prev" :disabled="busy||pageIndex===0" @click="load(pageIndex-1)">上一页尝试</button><span>第 {{pageIndex+1}} 页</span><button type="button" data-test="attempt-next" :disabled="busy||!result?.hasMore" @click="load(pageIndex+1)">下一页尝试</button></div></section></template>
